#!/usr/bin/env bash
# Gate (backlog row 165): every field of a `#[derive(Props)]` struct has a `///` doc comment.
#
# The docs site prints a props reference table on every component page, generated by `preview/build.rs`
# from the same scan (`preview/props_scan.rs`); a field with no doc comment would be a table row with an
# empty description. This gate fails on such a field, in `primitives/src/**` and in every
# `preview/src/components/*/component.rs`, so a prop cannot ship undocumented. A `#[props(extends = ..)]`
# spread is not a prop (the table says "plus the global attributes" once) and is exempt.
#
# The scanner is std-only, so a bare `rustc` builds it in about a second; no cargo lock needed.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."

out="${PROPS_SCAN_OUT:-$(mktemp -d)}"
trap '[ -n "${PROPS_SCAN_OUT:-}" ] || rm -rf "$out"' EXIT
rustc --edition 2021 -O -o "$out/props-scan" scripts/props-scan/main.rs 2>"$out/rustc.log" \
  || { cat "$out/rustc.log"; echo "check-props-docs: scanner failed to compile" >&2; exit 1; }

mapfile -t files < <({ find primitives/src -name '*.rs'; find preview/src/components -name component.rs; } | sort)
if "$out/props-scan" "${files[@]}"; then
  echo "check-props-docs: OK"
else
  echo "check-props-docs: FAIL -- document each field above with a \`///\` comment (it becomes the Description column of the component's props table)" >&2
  exit 1
fi
